<template>
    <div class="page">
        <appHeader :title='tits' :istop="num"></appHeader>
        <div class="main buhuos">
            <ul class="tabs">
                <li  @click="handleClick(1)" 
                    :class="stzh == 1 ? 'active' : 'default'">自动补货设定
                </li>
                <li   @click="handleClick(2)" 
                    :class="stzh == 2 ? 'active' : 'default'">自动补货变更记录
                </li>
            </ul>
            <div class="zdbhs" v-if="stzh == 1">
                <div class="buhuoset">
                    <div class="zd-select item">
                        <div class="zd-fbtn" @click="lxtab" style="width:115px;margin-left:2px;">
                            <div class="zd-fbtn-t">{{lotteryName}}</div>
                            <img class="zd-img" src="@/assets/images/adown.webp">
                        </div>
                        <van-stepper :show-minus="false" :show-plus="false" :min="0" integer @keyup.native="check_count" v-model="quickAmout"></van-stepper>
                        <div class="mbtns" @click="quickSet">套用</div>
                        <span style="margin-left: 5px;color: red;font-siz：12px;">0=不生效</span>
                    </div>
                    <div class="item" v-for="(lottery, index) in lotteryList" :key="index" v-show="lottery.lotteryId === activeName">
                        <table>
                            <thead>
                                <tr>
                                    <th>玩法</th>
                                    <th>货量限制</th>
                                </tr>
                            </thead>
                            <tbody>
                                <tr v-for="(item,index) in lottery.grsList" :key="index" :class="(index%2==0)?'eve':'old'">
                                    <td>{{ item.replenishstockName }}</td>
                                    <td>
                                        <van-stepper :show-minus="false" :show-plus="false" :min="0" integer @keyup.native="check_count" v-model="item.batAmount"></van-stepper>
                                    </td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                </div>
                <div class="fobtn">
                    <div @click="cances" class="fobcanl">取消</div>
                    <div class="fobmits"  @click="onSubmit" >确定</div>
                </div>
            </div>
            <div class="zdbhs" v-if="stzh == 2">
                <div style="display:flex;align-items:center;justify-content:space-between;margin:10px">
                    <div style="flex:1;overflow-x:auto;margin-left:-1px">
                        <table style="width:200%">
                           <thead>
                                <tr>
                                    <th class="user-u1">变更时间</th>
                                    <th>游戏名称</th>
                                    <th>变更类别</th>
                                    <th>原始值</th>
                                    <th>变更值</th>
                                    <th>变更人</th>
                                </tr>
                            </thead>
                            <tbody v-if="userLog && userLog.length>0">
                                <tr v-for="(item,index) in userLog" :key="index" :class="(index%2==0)?'eve':'old'">
                                    <td class="center user-u2">{{ item.createTime }}</td>
                                    <td class="center" >
                                        <div>{{ item.lotteryName }}</div>
                                    </td>
                                    <td class="center">
                                        <div>[{{ item.downOddsName }} 自动补货]</div>
                                    </td>
                                    <td class="center">
                                        <div>注额：{{ item.newReplenish }}</div>
                                    </td>
                                    <td class="center">
                                        <div>注额：{{ item.newReplenish }}</div>
                                    </td>
                                    <td class="center">{{ item.createBy }}(代理)</td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                </div>
                <div style="padding:10px 0" class="pages" v-if="param.pageSize">
                    <van-pagination
                            @change="handleCurrentChange"
                            v-model="param.pageNum"
                            :items-per-page="pages.pageSize"
                            :total-items="pages.total">
                    </van-pagination>
                </div>
            </div>
            <van-popup v-model:show="zdSelect" :overlay="false" position="bottom" class="popTop">
                <div class="pop-list">
                    <div class="pop-line">
                        <div class="pop-lines">
                            <div class="pop-list-line"></div>
                        </div>
                        <div class="pop-head">
                            <div class="pop-head-t">彩种选择</div>
                            <div @click="zdSelect=false" class="pop-head-img">关闭</div>
                        </div>
                    </div>
                    <div class="pop-cont">
                        <div class="flex-item">
                            <div class="yx-select" @click="activeAction(item)" :class="item.lotteryId==activeName?'active':''" v-for="item in lotteryList" :key="item.lotteryId">{{item.name}}</div>
                        </div> 
                    </div>
                </div>
            </van-popup>
        </div>
    </div>
</template>

<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { useUserStore } from '@/store/user'
import { showToast, showLoadingToast } from 'vant'
import { useTimeUtils } from '@/utils/time'
const userTime = useTimeUtils();

// 路由和状态管理
const router = useRouter()
const userStore = useUserStore()

// 响应式数据
const loading = ref(false);
const lotteryList = ref([]);
const list = ref([]);
const stzh = ref(1);
const activeName = ref('');
const quickAmout = ref('');
const quickStatus = ref('2');
const itens = ref({});
const userLog = ref([]);
const newList = ref([]);
const oddDialog = ref(false);
const lotteryName = ref('');
const zdSelect = ref(false);
const tits = ref("自动补货")
const num = ref(3)
// 赔率列表数据
const oddsList = ref([]);

const param = reactive({
    object: {},
    pageNum: 0,
    pageSize: 10,
});

const pages = reactive({
    pageNum: 0,
    total: 0,
});

// 方法定义
const check_count = (e) => {
    let obj = e.target;
    if (obj.value != '' && obj.value.substr(0, 1) == '.') {
        obj.value = 0;
    }
    if (!obj.value) {
        obj.value = 0;
    }
    obj.value = obj.value.replace(/^0*(0\.|[1-9])/, '$1');
    obj.value = obj.value.replace(/^(\-)*(\d+)\.(\d\d\d\d).*$/, '$1$2.$3');
    if (obj.value.indexOf(".") < 0 && obj.value != "") {
        if (obj.value.substr(0, 1) == '0' && obj.value.length == 2) {
            obj.value = obj.value.substr(1, obj.value.length);
        }
    }
};

const lxtab = () => {
    zdSelect.value = !zdSelect.value;
};

const cances = () => {
    if (activeName.value != 10101 && activeName.value != 10102) {
        
    }
    if (activeName.value == 10101 || activeName.value == 10102) {
        tclist.value.forEach(item => {
            item.batAmount = 0;
        });
    }
};

const quickSet = () => {
    if (activeName.value != 10101 && activeName.value != 10102) {
        oddsList.value.forEach(item => {
            item.batAmount = Number(quickAmout.value);
        });
    }
    if (activeName.value == 10101 || activeName.value == 10102) {
        tclist.value.forEach(item => {
            item.batAmount = Number(quickAmout.value);
        });
    }
};

const getHuhuo = async () => {
    loading.value = true;
    try {
        const res = await userStore.loadStock();
        lotteryList.value = res.data;
        activeName.value = lotteryList.value[0].lotteryId;
        lotteryName.value = lotteryList.value[0].name;
        itens.value = lotteryList.value[0];
        loading.value = false;
    } catch (error) {
        loading.value = false;
        console.log('获取补货设置失败:', error);
    }
};

const activeAction = async (items) => {
    activeName.value = items.lotteryId;
    lotteryName.value = items.name;
    itens.value = items;
    zdSelect.value = false;
};

const onSubmit = async () => {
    loading.value = true;
    let str = [];
    
    const loadingToast = showLoadingToast({
        message: '正在加载……',
        forbidClick: true,
        duration: 0,
    });
    
    // 5秒后自动关闭（保持与原逻辑一致）
    setTimeout(() => {
       loadingToast.close()
    }, 3000);
    
    try {
        const res = await userStore.setReplenSave(lotteryList.value);
        loading.value = false;
       loadingToast.close()
        if (res.code == 200) {
            await getHuhuo();
        }
    } catch (error) {
        loading.value = false;
        loadingToast.close()
        console.log('保存失败:', error);
    }
};

const handleClick = (num) => {
    stzh.value = num;
    if (stzh.value == 1) {
        getContent();
    } else {
        getUserLog();
    }
};

const handleSizeChange = (val) => {
    console.log(`每页 ${val} 条`);
};

const handleCurrentChange = (val) => {
    param.pageNum = val;
    getUserLog();
};

const getUserLog = async () => {
    try {
        const res = await userStore.getReplenish(param);
        userLog.value = res.data.list;
        pages.pageSize = res.data.pageSize;
        pages.total = res.data.total;
    } catch (error) {
        console.error('获取变更记录失败:', error);
        showToast({ type: 'error', message: '获取变更记录失败' });
    }
};

// 生命周期
onMounted(() => {
    getHuhuo();
});
</script>

<style scoped>
.zdbhs{
    height: calc(100vh - 150px);
    overflow-y:auto;
}
.item :deep(.van-stepper__input){
    width:100px !important;
    height: 35px !important;
    line-height: 35px !important;
    background: #FFFFFF 0% 0% no-repeat padding-box;
    box-shadow: inset 1px 1px 5px #00000033;
    border: 1px solid #D0D0D0;
    border-radius: 185px;
    font-size: 16px;
}
</style>